\set ON_ERROR_STOP on
begin;
create function pg_temp.assert_true(ok boolean, message text) returns void language plpgsql as $$ begin if ok is distinct from true then raise exception 'FAIL: %',message;end if;end $$;
create function pg_temp.assert_denied(statement text) returns void language plpgsql as $$ begin begin execute statement;exception when others then return;end;raise exception 'FAIL: statement was allowed: %',statement;end $$;
set local role anon;
select pg_temp.assert_denied($q$select public.arena_leaderboard('00000000-0000-4000-8000-000000000006')$q$);
set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000001',true);
select pg_temp.assert_denied('select * from public.arena_rooms');
select pg_temp.assert_denied('select * from public.arena_answers');
select pg_temp.assert_denied($q$select public.arena_create('00000000-0000-4000-8000-000000000007','arithmetic')$q$);
select pg_temp.assert_denied($q$select public.arena_create('00000000-0000-4000-8000-000000000006','invented')$q$);
select set_config('test.room',public.arena_create('00000000-0000-4000-8000-000000000006','arithmetic')::text,true);
select pg_temp.assert_true(public.arena_create('00000000-0000-4000-8000-000000000006','arithmetic')->>'id'=current_setting('test.room')::jsonb->>'id','create retries return the same room');
select pg_temp.assert_true(current_setting('test.room')::jsonb->'question'='null'::jsonb,'lobby does not expose question bank');
select pg_temp.assert_denied($q$select public.arena_start((current_setting('test.room')::jsonb->>'id')::uuid)$q$);
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000005',true);
select pg_temp.assert_denied($q$select public.arena_snapshot((current_setting('test.room')::jsonb->>'id')::uuid)$q$);
select pg_temp.assert_denied($q$select public.arena_leaderboard('00000000-0000-4000-8000-000000000006')$q$);
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000002',true);
select pg_temp.assert_true(jsonb_array_length(public.arena_join(current_setting('test.room')::jsonb->>'code')->'players')=2,'second device joins');
select pg_temp.assert_true(jsonb_array_length(public.arena_join(current_setting('test.room')::jsonb->>'code')->'players')=2,'join retry does not duplicate player');
select pg_temp.assert_denied($q$select public.arena_start((current_setting('test.room')::jsonb->>'id')::uuid)$q$);
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000001',true);
select pg_temp.assert_true(public.arena_start((current_setting('test.room')::jsonb->>'id')::uuid)->>'phase'='countdown','server starts countdown');
select pg_temp.assert_denied($q$select public.arena_answer((current_setting('test.room')::jsonb->>'id')::uuid,0,0)$q$);
select pg_temp.assert_denied($q$select public.arena_cancel((current_setting('test.room')::jsonb->>'id')::uuid)$q$);
reset role;
update public.arena_rooms set starts_at=clock_timestamp()-interval '2 seconds' where id=(current_setting('test.room')::jsonb->>'id')::uuid;
select set_config('test.answer',(select questions->0->>'answer' from public.arena_rooms where id=(current_setting('test.room')::jsonb->>'id')::uuid),true);
set local role authenticated;
select pg_temp.assert_true(not(public.arena_snapshot((current_setting('test.room')::jsonb->>'id')::uuid)->'question' ? 'answer'),'answer key stays private');
select pg_temp.assert_true(not(public.arena_snapshot((current_setting('test.room')::jsonb->>'id')::uuid)->'question' ? 'explanation'),'explanation stays private');
select pg_temp.assert_denied($q$select public.arena_answer((current_setting('test.room')::jsonb->>'id')::uuid,1,0)$q$);
select pg_temp.assert_denied($q$select public.arena_answer((current_setting('test.room')::jsonb->>'id')::uuid,0,null)$q$);
select pg_temp.assert_true(public.arena_answer((current_setting('test.room')::jsonb->>'id')::uuid,0,current_setting('test.answer')::integer)->'myAnswer'->'correct'='null'::jsonb,'no immediate correctness leak');
select pg_temp.assert_true(public.arena_answer((current_setting('test.room')::jsonb->>'id')::uuid,0,(current_setting('test.answer')::integer+1)%4)->'myAnswer'->>'choice'=current_setting('test.answer'),'retry cannot change answer');
select pg_temp.assert_true(not exists(select 1 from jsonb_array_elements(public.arena_snapshot((current_setting('test.room')::jsonb->>'id')::uuid)->'players') x where (x->>'points')::integer<>0),'live scores cannot leak correct answers');
select pg_temp.assert_true(not exists(select 1 from jsonb_array_elements(public.arena_leaderboard('00000000-0000-4000-8000-000000000006')) x where (x->>'points')::integer<>0),'unfinished matches do not enter leaderboard');
reset role;
select pg_temp.assert_true((select count(*)=1 from public.arena_answers where room_id=(current_setting('test.room')::jsonb->>'id')::uuid),'exactly one answer stored');
update public.arena_rooms set starts_at=clock_timestamp()-interval '16 seconds' where id=(current_setting('test.room')::jsonb->>'id')::uuid;
set local role authenticated;
select pg_temp.assert_true(public.arena_snapshot((current_setting('test.room')::jsonb->>'id')::uuid)->>'phase'='reveal','reveal follows server clock');
select pg_temp.assert_true(public.arena_snapshot((current_setting('test.room')::jsonb->>'id')::uuid)->'question' ? 'answer','answer is visible after deadline');
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000002',true);
select pg_temp.assert_denied($q$select public.arena_answer((current_setting('test.room')::jsonb->>'id')::uuid,0,0)$q$);
reset role;
update public.arena_rooms set starts_at=clock_timestamp()-interval '181 seconds' where id=(current_setting('test.room')::jsonb->>'id')::uuid;
set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-4000-8000-000000000001',true);
select pg_temp.assert_true(public.arena_snapshot((current_setting('test.room')::jsonb->>'id')::uuid)->>'phase'='finished','match ends without host requests');
select pg_temp.assert_true(jsonb_array_length(public.arena_snapshot((current_setting('test.room')::jsonb->>'id')::uuid)->'review')=10,'all ten rounds available for personal review');
select pg_temp.assert_true((public.arena_leaderboard('00000000-0000-4000-8000-000000000006')->0->>'points')::integer between 100 and 500,'completed score enters group leaderboard');
select pg_temp.assert_true(public.arena_leaderboard('00000000-0000-4000-8000-000000000006')->0->>'id'=auth.uid()::text,'winner ranks first');
select pg_temp.assert_true(not(public.arena_leaderboard('00000000-0000-4000-8000-000000000006')->0 ? 'code'),'private profile codes stay private');
reset role;
update public.profiles set active=false where id='00000000-0000-4000-8000-000000000001';
set local role authenticated;
select pg_temp.assert_denied($q$select public.arena_snapshot((current_setting('test.room')::jsonb->>'id')::uuid)$q$);
reset role;
update public.profiles set active=true where id='00000000-0000-4000-8000-000000000001';
delete from public.class_memberships where class_id='00000000-0000-4000-8000-000000000006' and profile_id='00000000-0000-4000-8000-000000000001';
set local role authenticated;
select pg_temp.assert_denied($q$select public.arena_leaderboard('00000000-0000-4000-8000-000000000006')$q$);
select pg_temp.assert_denied($q$select public.arena_snapshot((current_setting('test.room')::jsonb->>'id')::uuid)$q$);
rollback;
\echo 'Arena permissions, clocks, scoring, retry and leaderboard passed'
